-- =====================================================================
--  KULKASKU · setup database Supabase
--  Cara pakai: Supabase > SQL Editor > New query > tempel semua > Run
--  Aman dijalankan ulang.
-- =====================================================================

-- ---------- 1. Tabel profil (1 baris per akun) ----------
create table if not exists public.profil (
  id uuid primary key references auth.users(id) on delete cascade,
  username text unique not null,
  nama text not null default '',
  email text not null default '',
  hp text not null default '',
  foto text,
  ava text not null default 'brokoli',
  catatan text not null default 'tahu
daun bawang
susu',
  suhu_kl int not null default 4,
  suhu_fz int not null default -18,
  jam text not null default '07:00',
  pengingat boolean not null default true,
  kalender boolean not null default true,
  dibuat timestamptz not null default now()
);

-- ---------- 2. Isi kulkas ----------
create table if not exists public.bahan (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  nama text not null,
  jenis text not null,
  kat text not null default 'Sayur',
  jumlah numeric not null default 1,
  satuan text not null default 'buah',
  tempat text not null default 'rak' check (tempat in ('freezer','rak','laci','pintu')),
  beli date not null default current_date,
  awet int not null default 5 check (awet between 1 and 365),
  dibuat timestamptz not null default now()
);

-- ---------- 3. Riwayat (dipakai / dibuang) ----------
create table if not exists public.riwayat (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  nama text not null,
  jenis text not null,
  jumlah numeric not null default 1,
  satuan text not null default '',
  aksi text not null check (aksi in ('dipakai','dibuang')),
  waktu timestamptz not null default now()
);

-- ---------- 4. Katalog sayur & buah (dibaca aplikasi lewat API GET) ----------
create table if not exists public.katalog (
  id text primary key,
  label text not null,
  kat text not null,
  awet int not null,
  satuan text not null,
  tempat text not null,
  tint text not null,
  tips text not null,
  ide jsonb not null default '[]',
  urutan int not null default 0
);

-- ---------- 5. Keamanan: tiap akun hanya bisa melihat datanya sendiri ----------
alter table public.profil  enable row level security;
alter table public.bahan   enable row level security;
alter table public.riwayat enable row level security;
alter table public.katalog enable row level security;

drop policy if exists "profil milik sendiri" on public.profil;
create policy "profil milik sendiri" on public.profil
  for all using (auth.uid() = id) with check (auth.uid() = id);

drop policy if exists "bahan milik sendiri" on public.bahan;
create policy "bahan milik sendiri" on public.bahan
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

drop policy if exists "riwayat milik sendiri" on public.riwayat;
create policy "riwayat milik sendiri" on public.riwayat
  for all using (auth.uid() = user_id) with check (auth.uid() = user_id);

drop policy if exists "katalog boleh dibaca semua" on public.katalog;
create policy "katalog boleh dibaca semua" on public.katalog
  for select using (true);

-- ---------- 6. Profil dibuat otomatis saat daftar ----------
create or replace function public.buat_profil_baru()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  values (
    new.id,
    lower(coalesce(new.raw_user_meta_data->>'username', split_part(new.email, '@', 1))),
    coalesce(new.raw_user_meta_data->>'nama', ''),
    new.email,
    coalesce(new.raw_user_meta_data->>'hp', '')
  )
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists saat_daftar on auth.users;
create trigger saat_daftar after insert on auth.users
  for each row execute procedure public.buat_profil_baru();

-- ---------- 7. Fungsi bantu untuk login pakai username ----------
create or replace function public.email_by_username(uname text)
returns text language sql security definer set search_path = public as $$
  select email from public.profil where username = lower(uname) limit 1;
$$;

create or replace function public.username_dipakai(uname text)
returns boolean language sql security definer set search_path = public as $$
  select exists (select 1 from public.profil where username = lower(uname));
$$;

-- Hapus akun sendiri beserta semua datanya (tabel lain ikut terhapus lewat cascade)
create or replace function public.hapus_akun()
returns void language plpgsql security definer set search_path = public as $$
begin
  -- foto profil dihapus dulu oleh aplikasi lewat Storage API
  delete from auth.users where id = auth.uid();
end $$;

-- Hak akses tabel lewat Data API (tetap dijaga Row Level Security di atas)
grant usage on schema public to anon, authenticated;
grant select on public.katalog to anon, authenticated;
grant select, insert, update, delete on public.profil, public.bahan, public.riwayat to authenticated;

grant execute on function public.email_by_username(text) to anon, authenticated;
grant execute on function public.username_dipakai(text) to anon, authenticated;
grant execute on function public.hapus_akun() to authenticated;

-- ---------- 8. Storage untuk foto profil ----------
values ('avatar', 'avatar', true)
on conflict (id) do nothing;

drop policy if exists "foto: siapa saja boleh lihat" on storage.objects;
create policy "foto: siapa saja boleh lihat" on storage.objects
  for select using (bucket_id = 'avatar');

drop policy if exists "foto: upload ke folder sendiri" on storage.objects;
create policy "foto: upload ke folder sendiri" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'avatar' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists "foto: ubah milik sendiri" on storage.objects;
create policy "foto: ubah milik sendiri" on storage.objects
  for update to authenticated
  using (bucket_id = 'avatar' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists "foto: hapus milik sendiri" on storage.objects;
create policy "foto: hapus milik sendiri" on storage.objects
  for delete to authenticated
  using (bucket_id = 'avatar' and (storage.foldername(name))[1] = auth.uid()::text);

